-- ECO201: a new course
select is((select content_key from public.courses where id = 'da06b311-1382-53a8-8057-d3513764c222' and is_shared is null),
  'introduction-microeconomics', 'ECO201: the new repository identity is registered, its sharing unresolved');
select is((select is_free from public.institutional_courses where course_code = 'ECO201'), false,
  'ECO201: the course is not free');
select is((select repository_course_id from public.institutional_courses where course_code = 'ECO201'),
  'da06b311-1382-53a8-8057-d3513764c222'::uuid, 'ECO201: its catalogue course links to it');
select is((select display_title from public.institutional_courses where course_code = 'ECO201'),
  'Introduction to Microeconomics', 'ECO201: the catalogue shows the official title');
select is((select array_agg(distinct p.key order by p.key) from public.course_applicability a
  join public.academic_levels l on l.id = a.academic_level_id join public.academic_periods p on p.id = a.academic_period_id
  where a.institutional_course_id = (select id from public.institutional_courses where course_code = 'ECO201') and l.key = '200-level'),
  array['first-semester']::text[],
  'ECO201: it applies at the official level in every official semester');
-- Apply refuses a catalogue course missing from an official semester; the removed rows are then put back.
create temporary table bank_applicability_official_bank_eco201 on commit drop as
  select * from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'ECO201');
delete from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'ECO201')
  and academic_period_id = (select id from public.academic_periods where key = 'first-semester');
select throws_ok($$select private.official_bank_eco201('apply')$$, 'P0001',
  'Official bank ECO201: the catalogue course does not apply at the official level in every official semester',
  'ECO201: apply refuses a catalogue course missing from an official semester');
insert into public.course_applicability select * from bank_applicability_official_bank_eco201
