select is(private.official_bank_eco201('apply'), 'unchanged', 'ECO201: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_eco201), 'ECO201: a rerun writes nothing');

select is(private.official_bank_eco201('rollback'), 'rolled-back', 'ECO201: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'da06b311-1382-53a8-8057-d3513764c222' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'ECO201: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = 'da06b311-1382-53a8-8057-d3513764c222'
  and kind = 'cbt_question'), 820, 'ECO201: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = 'da06b311-1382-53a8-8057-d3513764c222' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 820,
  'ECO201: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_eco201('rollback'), 'unchanged', 'ECO201: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '01473ba7-6c53-5476-ad78-d3cf016e0ce0';
select throws_ok($$select private.official_bank_eco201('apply')$$, 'P0001',
  'Official bank ECO201: the published questions are not the audited set',
  'ECO201: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '01473ba7-6c53-5476-ad78-d3cf016e0ce0';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_eco201 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = '9f899cda-44dc-55df-bf31-1a66a11f496f' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = '9f899cda-44dc-55df-bf31-1a66a11f496f' and revision = 1;
select throws_ok($$select private.official_bank_eco201('apply')$$, 'P0001',
  'Official bank ECO201: 9f899cda-44dc-55df-bf31-1a66a11f496f is not the same migration-owned question',
  'ECO201: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'da06b311-1382-53a8-8057-d3513764c222' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'ECO201: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_eco201)
  where item_id = '9f899cda-44dc-55df-bf31-1a66a11f496f' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_eco201),
  'ECO201: the failed apply wrote nothing');

select is(private.official_bank_eco201('apply'), 'applied', 'ECO201: apply after a rollback republishes the bank set');
