  join public.academic_levels l on l.id = a.academic_level_id join public.academic_periods p on p.id = a.academic_period_id
  where a.institutional_course_id = (select id from public.institutional_courses where course_code = 'LAG-ACS209') and l.key = '200-level'),
  array['first-semester']::text[],
  'LAG-ACS209: it applies at the official level in every official semester');
-- Apply refuses a catalogue course missing from an official semester; the removed rows are then put back.
create temporary table bank_applicability_official_bank_lag_acs209 on commit drop as
  select * from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'LAG-ACS209');
delete from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'LAG-ACS209')
  and academic_period_id = (select id from public.academic_periods where key = 'first-semester');
select throws_ok($$select private.official_bank_lag_acs209('apply')$$, 'P0001',
  'Official bank LAG-ACS209: the catalogue course does not apply at the official level in every official semester',
  'LAG-ACS209: apply refuses a catalogue course missing from an official semester');
insert into public.course_applicability select * from bank_applicability_official_bank_lag_acs209
  where (institutional_course_id, department_id, academic_level_id, academic_period_id) not in
    (select institutional_course_id, department_id, academic_level_id, academic_period_id from public.course_applicability);
-- LAG-ACS209 (business-statistics-1)
