select is((select count(*)::int from public.managed_content_items where course_id = '66dc36be-2c4d-5821-ac32-a5c8e4ae4886'
  and kind = 'cbt_question'), 864,
  'LAG-ACS209: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_lag_acs209 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_lag_acs209('apply'), 'unchanged', 'LAG-ACS209: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_lag_acs209), 'LAG-ACS209: a rerun writes nothing');

select is(private.official_bank_lag_acs209('rollback'), 'rolled-back', 'LAG-ACS209: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '66dc36be-2c4d-5821-ac32-a5c8e4ae4886' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'LAG-ACS209: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = '66dc36be-2c4d-5821-ac32-a5c8e4ae4886'
  and kind = 'cbt_question'), 864, 'LAG-ACS209: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = '66dc36be-2c4d-5821-ac32-a5c8e4ae4886' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 864,
  'LAG-ACS209: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_lag_acs209('rollback'), 'unchanged', 'LAG-ACS209: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = 'bab24262-8041-5e0d-aaec-1e84c5ef9974';
select throws_ok($$select private.official_bank_lag_acs209('apply')$$, 'P0001',
  'Official bank LAG-ACS209: the published questions are not the audited set',
  'LAG-ACS209: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = 'bab24262-8041-5e0d-aaec-1e84c5ef9974';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_lag_acs209 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = 'dd3cb12c-8f45-564d-ab7d-b3b96476836a' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = 'dd3cb12c-8f45-564d-ab7d-b3b96476836a' and revision = 1;
select throws_ok($$select private.official_bank_lag_acs209('apply')$$, 'P0001',
  'Official bank LAG-ACS209: dd3cb12c-8f45-564d-ab7d-b3b96476836a is not the same migration-owned question',
  'LAG-ACS209: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '66dc36be-2c4d-5821-ac32-a5c8e4ae4886' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'LAG-ACS209: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_lag_acs209)
  where item_id = 'dd3cb12c-8f45-564d-ab7d-b3b96476836a' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_lag_acs209),
  'LAG-ACS209: the failed apply wrote nothing');

select is(private.official_bank_lag_acs209('apply'), 'applied', 'LAG-ACS209: apply after a rollback republishes the bank set');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
