  array['first-semester']::text[],
  'LAG-ACS213: it applies at the official level in every official semester');
-- Apply refuses a catalogue course missing from an official semester; the removed rows are then put back.
create temporary table bank_applicability_official_bank_lag_acs213 on commit drop as
  select * from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'LAG-ACS213');
delete from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'LAG-ACS213')
  and academic_period_id = (select id from public.academic_periods where key = 'first-semester');
select throws_ok($$select private.official_bank_lag_acs213('apply')$$, 'P0001',
  'Official bank LAG-ACS213: the catalogue course does not apply at the official level in every official semester',
  'LAG-ACS213: apply refuses a catalogue course missing from an official semester');
insert into public.course_applicability select * from bank_applicability_official_bank_lag_acs213
  where (institutional_course_id, department_id, academic_level_id, academic_period_id) not in
    (select institutional_course_id, department_id, academic_level_id, academic_period_id from public.course_applicability);
