select is((select count(*)::int from public.managed_content_items where course_id = 'e6ebc3e3-e990-5459-84af-06a4f05aea89'
  and kind = 'cbt_question'), 1262,
  'LAG-ACS213: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_lag_acs213 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_lag_acs213('apply'), 'unchanged', 'LAG-ACS213: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_lag_acs213), 'LAG-ACS213: a rerun writes nothing');

select is(private.official_bank_lag_acs213('rollback'), 'rolled-back', 'LAG-ACS213: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'e6ebc3e3-e990-5459-84af-06a4f05aea89' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'LAG-ACS213: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = 'e6ebc3e3-e990-5459-84af-06a4f05aea89'
  and kind = 'cbt_question'), 1262, 'LAG-ACS213: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = 'e6ebc3e3-e990-5459-84af-06a4f05aea89' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 1262,
  'LAG-ACS213: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_lag_acs213('rollback'), 'unchanged', 'LAG-ACS213: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = 'e4abf00a-b425-52bb-8682-37e3a43136cd';
select throws_ok($$select private.official_bank_lag_acs213('apply')$$, 'P0001',
  'Official bank LAG-ACS213: the published questions are not the audited set',
  'LAG-ACS213: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = 'e4abf00a-b425-52bb-8682-37e3a43136cd';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_lag_acs213 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = '25c47a89-51f9-5694-b619-6609d76ab254' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = '25c47a89-51f9-5694-b619-6609d76ab254' and revision = 1;
select throws_ok($$select private.official_bank_lag_acs213('apply')$$, 'P0001',
  'Official bank LAG-ACS213: 25c47a89-51f9-5694-b619-6609d76ab254 is not the same migration-owned question',
  'LAG-ACS213: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'e6ebc3e3-e990-5459-84af-06a4f05aea89' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'LAG-ACS213: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_lag_acs213)
  where item_id = '25c47a89-51f9-5694-b619-6609d76ab254' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_lag_acs213),
  'LAG-ACS213: the failed apply wrote nothing');

select is(private.official_bank_lag_acs213('apply'), 'applied', 'LAG-ACS213: apply after a rollback republishes the bank set');
