  'Elements of Banking', 'FIN-CM209: the catalogue shows the official title');
select is((select array_agg(distinct p.key order by p.key) from public.course_applicability a
  join public.academic_levels l on l.id = a.academic_level_id join public.academic_periods p on p.id = a.academic_period_id
  where a.institutional_course_id = (select id from public.institutional_courses where course_code = 'FIN-CM209') and l.key = '200-level'),
  array['first-semester', 'second-semester']::text[],
  'FIN-CM209: it applies at the official level in every official semester');
-- Apply refuses a catalogue course missing from an official semester; the removed rows are then put back.
create temporary table bank_applicability_official_bank_fin_cm209 on commit drop as
  select * from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'FIN-CM209');
delete from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'FIN-CM209')
  and academic_period_id = (select id from public.academic_periods where key = 'first-semester');
select throws_ok($$select private.official_bank_fin_cm209('apply')$$, 'P0001',
  'Official bank FIN-CM209: the catalogue course does not apply at the official level in every official semester',
  'FIN-CM209: apply refuses a catalogue course missing from an official semester');
insert into public.course_applicability select * from bank_applicability_official_bank_fin_cm209
  where (institutional_course_id, department_id, academic_level_id, academic_period_id) not in
    (select institutional_course_id, department_id, academic_level_id, academic_period_id from public.course_applicability);
-- FIN-CM209 (elements-banking)
