select is((select count(*)::int from public.managed_content_items where course_id = '58f61fa3-cc23-5d99-bde7-5581043985ed'
  and kind = 'cbt_question'), 1445,
  'FIN-CM209: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_fin_cm209 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_fin_cm209('apply'), 'unchanged', 'FIN-CM209: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_fin_cm209), 'FIN-CM209: a rerun writes nothing');

select is(private.official_bank_fin_cm209('rollback'), 'rolled-back', 'FIN-CM209: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '58f61fa3-cc23-5d99-bde7-5581043985ed' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'FIN-CM209: rollback republishes exactly the audited set at revision one');
select is((select display_title from public.institutional_courses where repository_course_id = '58f61fa3-cc23-5d99-bde7-5581043985ed'),
  'Element of Banking', 'FIN-CM209: rollback restores the catalogue title');
select is((select count(*)::int from public.managed_content_items where course_id = '58f61fa3-cc23-5d99-bde7-5581043985ed'
  and kind = 'cbt_question'), 1445, 'FIN-CM209: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = '58f61fa3-cc23-5d99-bde7-5581043985ed' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 1445,
  'FIN-CM209: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_fin_cm209('rollback'), 'unchanged', 'FIN-CM209: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '3d5efc40-b71a-508f-a925-3a7cee06b0d5';
select throws_ok($$select private.official_bank_fin_cm209('apply')$$, 'P0001',
  'Official bank FIN-CM209: the published questions are not the audited set',
  'FIN-CM209: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '3d5efc40-b71a-508f-a925-3a7cee06b0d5';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_fin_cm209 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = '7d2ceb31-0de0-55bf-a330-864ee34b5303' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = '7d2ceb31-0de0-55bf-a330-864ee34b5303' and revision = 1;
select throws_ok($$select private.official_bank_fin_cm209('apply')$$, 'P0001',
  'Official bank FIN-CM209: 7d2ceb31-0de0-55bf-a330-864ee34b5303 is not the same migration-owned question',
  'FIN-CM209: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '58f61fa3-cc23-5d99-bde7-5581043985ed' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'FIN-CM209: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_fin_cm209)
  where item_id = '7d2ceb31-0de0-55bf-a330-864ee34b5303' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_fin_cm209),
  'FIN-CM209: the failed apply wrote nothing');

select is(private.official_bank_fin_cm209('apply'), 'applied', 'FIN-CM209: apply after a rollback republishes the bank set');
