-- AMS101: a new course
select is((select content_key from public.courses where id = 'fa9abff6-1f94-5735-bbd3-c9104da6df05' and is_shared is null),
  'principles-management', 'AMS101: the new repository identity is registered, its sharing unresolved');
select is((select is_free from public.institutional_courses where course_code = 'AMS101'), false,
  'AMS101: the course is not free');
select is((select repository_course_id from public.institutional_courses where course_code = 'AMS101'),
  'fa9abff6-1f94-5735-bbd3-c9104da6df05'::uuid, 'AMS101: its catalogue course links to it');
select is((select display_title from public.institutional_courses where course_code = 'AMS101'),
  'Principles of Management', 'AMS101: the catalogue shows the official title');
select is((select array_agg(distinct p.key order by p.key) from public.course_applicability a
  join public.academic_levels l on l.id = a.academic_level_id join public.academic_periods p on p.id = a.academic_period_id
  where a.institutional_course_id = (select id from public.institutional_courses where course_code = 'AMS101') and l.key = '100-level'),
  array['first-semester']::text[],
  'AMS101: it applies at the official level in every official semester');
-- Apply refuses a catalogue course missing from an official semester; the removed rows are then put back.
create temporary table bank_applicability_official_bank_ams101 on commit drop as
  select * from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'AMS101');
delete from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'AMS101')
  and academic_period_id = (select id from public.academic_periods where key = 'first-semester');
select throws_ok($$select private.official_bank_ams101('apply')$$, 'P0001',
  'Official bank AMS101: the catalogue course does not apply at the official level in every official semester',
