select is((select count(*)::int from public.managed_content_items where course_id = 'fa9abff6-1f94-5735-bbd3-c9104da6df05'
  and kind = 'cbt_question'), 2204,
  'AMS101: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_ams101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_ams101('apply'), 'unchanged', 'AMS101: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_ams101), 'AMS101: a rerun writes nothing');

select is(private.official_bank_ams101('rollback'), 'rolled-back', 'AMS101: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'fa9abff6-1f94-5735-bbd3-c9104da6df05' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'AMS101: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = 'fa9abff6-1f94-5735-bbd3-c9104da6df05'
  and kind = 'cbt_question'), 2204, 'AMS101: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = 'fa9abff6-1f94-5735-bbd3-c9104da6df05' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 2204,
  'AMS101: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_ams101('rollback'), 'unchanged', 'AMS101: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '20b4bffc-b7c3-51c9-b2ee-0eed40a7bcc1';
select throws_ok($$select private.official_bank_ams101('apply')$$, 'P0001',
  'Official bank AMS101: the published questions are not the audited set',
  'AMS101: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '20b4bffc-b7c3-51c9-b2ee-0eed40a7bcc1';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_ams101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = '4b065c8f-d0c4-5970-8e83-a63cde928d4b' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = '4b065c8f-d0c4-5970-8e83-a63cde928d4b' and revision = 1;
select throws_ok($$select private.official_bank_ams101('apply')$$, 'P0001',
  'Official bank AMS101: 4b065c8f-d0c4-5970-8e83-a63cde928d4b is not the same migration-owned question',
  'AMS101: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'fa9abff6-1f94-5735-bbd3-c9104da6df05' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'AMS101: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_ams101)
  where item_id = '4b065c8f-d0c4-5970-8e83-a63cde928d4b' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_ams101),
  'AMS101: the failed apply wrote nothing');

select is(private.official_bank_ams101('apply'), 'applied', 'AMS101: apply after a rollback republishes the bank set');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
