select is((select count(*)::int from public.managed_content_items where course_id = '0264c494-3ae3-5279-b2a2-2ae91167839e'
  and kind = 'cbt_question'), 1273,
  'AMS103: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_ams103 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_ams103('apply'), 'unchanged', 'AMS103: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_ams103), 'AMS103: a rerun writes nothing');

select is(private.official_bank_ams103('rollback'), 'rolled-back', 'AMS103: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '0264c494-3ae3-5279-b2a2-2ae91167839e' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'AMS103: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = '0264c494-3ae3-5279-b2a2-2ae91167839e'
  and kind = 'cbt_question'), 1273, 'AMS103: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = '0264c494-3ae3-5279-b2a2-2ae91167839e' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 1273,
  'AMS103: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_ams103('rollback'), 'unchanged', 'AMS103: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '1f6faa52-2070-56b3-bfec-5f6345a7a82b';
select throws_ok($$select private.official_bank_ams103('apply')$$, 'P0001',
  'Official bank AMS103: the published questions are not the audited set',
  'AMS103: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '1f6faa52-2070-56b3-bfec-5f6345a7a82b';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_ams103 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = 'ffd62933-a562-51c8-912a-af4d1a5ba0c3' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = 'ffd62933-a562-51c8-912a-af4d1a5ba0c3' and revision = 1;
select throws_ok($$select private.official_bank_ams103('apply')$$, 'P0001',
  'Official bank AMS103: ffd62933-a562-51c8-912a-af4d1a5ba0c3 is not the same migration-owned question',
  'AMS103: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '0264c494-3ae3-5279-b2a2-2ae91167839e' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'AMS103: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_ams103)
  where item_id = 'ffd62933-a562-51c8-912a-af4d1a5ba0c3' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_ams103),
  'AMS103: the failed apply wrote nothing');

