select is((select count(*)::int from public.managed_content_items where course_id = 'bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a'
  and kind = 'cbt_question'), 587,
  'ACC101: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_acc101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_acc101('apply'), 'unchanged', 'ACC101: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_acc101), 'ACC101: a rerun writes nothing');

select is(private.official_bank_acc101('rollback'), 'rolled-back', 'ACC101: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'ACC101: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = 'bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a'
  and kind = 'cbt_question'), 587, 'ACC101: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = 'bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 587,
  'ACC101: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_acc101('rollback'), 'unchanged', 'ACC101: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '4237fb07-7b69-58c7-8666-518268bc9d50';
select throws_ok($$select private.official_bank_acc101('apply')$$, 'P0001',
  'Official bank ACC101: the published questions are not the audited set',
  'ACC101: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '4237fb07-7b69-58c7-8666-518268bc9d50';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_acc101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = '28c73f1e-7bf4-50ac-a092-ba8fb759271c' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = '28c73f1e-7bf4-50ac-a092-ba8fb759271c' and revision = 1;
select throws_ok($$select private.official_bank_acc101('apply')$$, 'P0001',
  'Official bank ACC101: 28c73f1e-7bf4-50ac-a092-ba8fb759271c is not the same migration-owned question',
  'ACC101: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'bf4eae11-b8cf-51d1-bfb1-5f32b1b2d55a' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'ACC101: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_acc101)
  where item_id = '28c73f1e-7bf4-50ac-a092-ba8fb759271c' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_acc101),
  'ACC101: the failed apply wrote nothing');

select is(private.official_bank_acc101('apply'), 'applied', 'ACC101: apply after a rollback republishes the bank set');
