select is((select count(*)::int from public.managed_content_items where course_id = 'e01c0d3f-3f5e-5197-b96f-ac7935fc2fe8'
  and kind = 'cbt_question'), 916,
  'ECO101: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_eco101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_eco101('apply'), 'unchanged', 'ECO101: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_eco101), 'ECO101: a rerun writes nothing');

select is(private.official_bank_eco101('rollback'), 'rolled-back', 'ECO101: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'e01c0d3f-3f5e-5197-b96f-ac7935fc2fe8' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'ECO101: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = 'e01c0d3f-3f5e-5197-b96f-ac7935fc2fe8'
  and kind = 'cbt_question'), 916, 'ECO101: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = 'e01c0d3f-3f5e-5197-b96f-ac7935fc2fe8' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 916,
  'ECO101: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_eco101('rollback'), 'unchanged', 'ECO101: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = 'b7bb76ac-5f9e-5df9-9bc8-fb1c6985f19f';
select throws_ok($$select private.official_bank_eco101('apply')$$, 'P0001',
  'Official bank ECO101: the published questions are not the audited set',
  'ECO101: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = 'b7bb76ac-5f9e-5df9-9bc8-fb1c6985f19f';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_eco101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = 'ec413da7-1060-5598-9ea1-e1461b853277' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = 'ec413da7-1060-5598-9ea1-e1461b853277' and revision = 1;
select throws_ok($$select private.official_bank_eco101('apply')$$, 'P0001',
  'Official bank ECO101: ec413da7-1060-5598-9ea1-e1461b853277 is not the same migration-owned question',
  'ECO101: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'e01c0d3f-3f5e-5197-b96f-ac7935fc2fe8' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'ECO101: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_eco101)
  where item_id = 'ec413da7-1060-5598-9ea1-e1461b853277' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_eco101),
  'ECO101: the failed apply wrote nothing');

select is(private.official_bank_eco101('apply'), 'applied', 'ECO101: apply after a rollback republishes the bank set');
