select is((select count(*)::int from public.managed_content_items where course_id = '3377fae6-5ab9-5742-95e3-75b94650a294'
  and kind = 'cbt_question'), 389,
  'BUA101: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_bua101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_bua101('apply'), 'unchanged', 'BUA101: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_bua101), 'BUA101: a rerun writes nothing');

select is(private.official_bank_bua101('rollback'), 'rolled-back', 'BUA101: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '3377fae6-5ab9-5742-95e3-75b94650a294' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'BUA101: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = '3377fae6-5ab9-5742-95e3-75b94650a294'
  and kind = 'cbt_question'), 389, 'BUA101: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = '3377fae6-5ab9-5742-95e3-75b94650a294' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 389,
  'BUA101: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_bua101('rollback'), 'unchanged', 'BUA101: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '4e1c5755-c2c5-5cb6-9c49-08aa47e35b13';
select throws_ok($$select private.official_bank_bua101('apply')$$, 'P0001',
  'Official bank BUA101: the published questions are not the audited set',
  'BUA101: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '4e1c5755-c2c5-5cb6-9c49-08aa47e35b13';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_bua101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = '886e5a09-83f2-58f8-9f9f-1823300c6857' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = '886e5a09-83f2-58f8-9f9f-1823300c6857' and revision = 1;
select throws_ok($$select private.official_bank_bua101('apply')$$, 'P0001',
  'Official bank BUA101: 886e5a09-83f2-58f8-9f9f-1823300c6857 is not the same migration-owned question',
  'BUA101: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '3377fae6-5ab9-5742-95e3-75b94650a294' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'BUA101: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_bua101)
  where item_id = '886e5a09-83f2-58f8-9f9f-1823300c6857' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_bua101),
  'BUA101: the failed apply wrote nothing');

