select is((select count(*)::int from public.managed_content_items where course_id = '203d7e61-c829-5419-a664-5a478e05a8a6'
  and kind = 'cbt_question'), 305,
  'FIN101: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_fin101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_fin101('apply'), 'unchanged', 'FIN101: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_fin101), 'FIN101: a rerun writes nothing');

select is(private.official_bank_fin101('rollback'), 'rolled-back', 'FIN101: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '203d7e61-c829-5419-a664-5a478e05a8a6' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'FIN101: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = '203d7e61-c829-5419-a664-5a478e05a8a6'
  and kind = 'cbt_question'), 305, 'FIN101: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = '203d7e61-c829-5419-a664-5a478e05a8a6' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 305,
  'FIN101: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_fin101('rollback'), 'unchanged', 'FIN101: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = 'f57c77e5-649b-575a-b49b-7b0a97d45dfe';
select throws_ok($$select private.official_bank_fin101('apply')$$, 'P0001',
  'Official bank FIN101: the published questions are not the audited set',
  'FIN101: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = 'f57c77e5-649b-575a-b49b-7b0a97d45dfe';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_fin101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = 'e019e9aa-4af4-59bd-87a1-918d12cfa5f9' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = 'e019e9aa-4af4-59bd-87a1-918d12cfa5f9' and revision = 1;
select throws_ok($$select private.official_bank_fin101('apply')$$, 'P0001',
  'Official bank FIN101: e019e9aa-4af4-59bd-87a1-918d12cfa5f9 is not the same migration-owned question',
  'FIN101: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '203d7e61-c829-5419-a664-5a478e05a8a6' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'FIN101: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_fin101)
  where item_id = 'e019e9aa-4af4-59bd-87a1-918d12cfa5f9' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_fin101),
  'FIN101: the failed apply wrote nothing');

