-- INS101: a new course
select is((select content_key from public.courses where id = 'cd0f182c-a770-5232-892c-22fdc00d8686' and is_shared is null),
  'introduction-insurance', 'INS101: the new repository identity is registered, its sharing unresolved');
select is((select is_free from public.institutional_courses where course_code = 'INS101'), false,
  'INS101: the course is not free');
select is((select repository_course_id from public.institutional_courses where course_code = 'INS101'),
  'cd0f182c-a770-5232-892c-22fdc00d8686'::uuid, 'INS101: its catalogue course links to it');
select is((select display_title from public.institutional_courses where course_code = 'INS101'),
  'Introduction to Insurance', 'INS101: the catalogue shows the official title');
select is((select array_agg(distinct p.key order by p.key) from public.course_applicability a
  join public.academic_levels l on l.id = a.academic_level_id join public.academic_periods p on p.id = a.academic_period_id
  where a.institutional_course_id = (select id from public.institutional_courses where course_code = 'INS101') and l.key = '100-level'),
  array['first-semester']::text[],
  'INS101: it applies at the official level in every official semester');
-- Apply refuses a catalogue course missing from an official semester; the removed rows are then put back.
create temporary table bank_applicability_official_bank_ins101 on commit drop as
  select * from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'INS101');
delete from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'INS101')
  and academic_period_id = (select id from public.academic_periods where key = 'first-semester');
select throws_ok($$select private.official_bank_ins101('apply')$$, 'P0001',
  'Official bank INS101: the catalogue course does not apply at the official level in every official semester',
  'INS101: apply refuses a catalogue course missing from an official semester');
insert into public.course_applicability select * from bank_applicability_official_bank_ins101
  where (institutional_course_id, department_id, academic_level_id, academic_period_id) not in
    (select institutional_course_id, department_id, academic_level_id, academic_period_id from public.course_applicability);
-- INS101 (introduction-insurance)
select is((select count(*)::int from public.managed_content_items where course_id = 'cd0f182c-a770-5232-892c-22fdc00d8686'
  and kind = 'cbt_question' and published_revision is not null), 458,
  'INS101: the final published count equals the bank count');
