-- SOC101: a new course
select is((select content_key from public.courses where id = 'f0a98038-5829-537e-bb07-a06605f6e2a4' and is_shared is null),
  'introduction-sociology-1', 'SOC101: the new repository identity is registered, its sharing unresolved');
select is((select is_free from public.institutional_courses where course_code = 'SOC101'), false,
  'SOC101: the course is not free');
select is((select repository_course_id from public.institutional_courses where course_code = 'SOC101'),
  'f0a98038-5829-537e-bb07-a06605f6e2a4'::uuid, 'SOC101: its catalogue course links to it');
select is((select display_title from public.institutional_courses where course_code = 'SOC101'),
  'Introduction to Sociology I', 'SOC101: the catalogue shows the official title');
select is((select array_agg(distinct p.key order by p.key) from public.course_applicability a
  join public.academic_levels l on l.id = a.academic_level_id join public.academic_periods p on p.id = a.academic_period_id
  where a.institutional_course_id = (select id from public.institutional_courses where course_code = 'SOC101') and l.key = '100-level'),
  array['first-semester']::text[],
  'SOC101: it applies at the official level in every official semester');
-- Apply refuses a catalogue course missing from an official semester; the removed rows are then put back.
create temporary table bank_applicability_official_bank_soc101 on commit drop as
  select * from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'SOC101');
delete from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'SOC101')
  and academic_period_id = (select id from public.academic_periods where key = 'first-semester');
select throws_ok($$select private.official_bank_soc101('apply')$$, 'P0001',
  'Official bank SOC101: the catalogue course does not apply at the official level in every official semester',
  'SOC101: apply refuses a catalogue course missing from an official semester');
insert into public.course_applicability select * from bank_applicability_official_bank_soc101
  where (institutional_course_id, department_id, academic_level_id, academic_period_id) not in
    (select institutional_course_id, department_id, academic_level_id, academic_period_id from public.course_applicability);
-- SOC101 (introduction-sociology-1)
select is((select count(*)::int from public.managed_content_items where course_id = 'f0a98038-5829-537e-bb07-a06605f6e2a4'
  and kind = 'cbt_question' and published_revision is not null), 523,
