select is((select count(*)::int from public.managed_content_items where course_id = 'f0a98038-5829-537e-bb07-a06605f6e2a4'
  and kind = 'cbt_question'), 523,
  'SOC101: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_soc101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_soc101('apply'), 'unchanged', 'SOC101: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_soc101), 'SOC101: a rerun writes nothing');

select is(private.official_bank_soc101('rollback'), 'rolled-back', 'SOC101: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'f0a98038-5829-537e-bb07-a06605f6e2a4' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'SOC101: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = 'f0a98038-5829-537e-bb07-a06605f6e2a4'
  and kind = 'cbt_question'), 523, 'SOC101: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = 'f0a98038-5829-537e-bb07-a06605f6e2a4' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 523,
  'SOC101: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_soc101('rollback'), 'unchanged', 'SOC101: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '697efd28-69ec-5e11-9a0b-ca37b3017d3d';
select throws_ok($$select private.official_bank_soc101('apply')$$, 'P0001',
  'Official bank SOC101: the published questions are not the audited set',
  'SOC101: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '697efd28-69ec-5e11-9a0b-ca37b3017d3d';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_soc101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = '5eb2c1e8-046f-5902-989d-fbd99e88f84e' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = '5eb2c1e8-046f-5902-989d-fbd99e88f84e' and revision = 1;
select throws_ok($$select private.official_bank_soc101('apply')$$, 'P0001',
  'Official bank SOC101: 5eb2c1e8-046f-5902-989d-fbd99e88f84e is not the same migration-owned question',
  'SOC101: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'f0a98038-5829-537e-bb07-a06605f6e2a4' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'SOC101: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_soc101)
  where item_id = '5eb2c1e8-046f-5902-989d-fbd99e88f84e' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_soc101),
  'SOC101: the failed apply wrote nothing');

select is(private.official_bank_soc101('apply'), 'applied', 'SOC101: apply after a rollback republishes the bank set');
