-- PUL101: a new course
select is((select content_key from public.courses where id = '4df568c2-4a68-52ab-80d6-380e5921d119' and is_shared is null),
  'legal-methods-1', 'PUL101: the new repository identity is registered, its sharing unresolved');
select is((select is_free from public.institutional_courses where course_code = 'PUL101'), false,
  'PUL101: the course is not free');
select is((select repository_course_id from public.institutional_courses where course_code = 'PUL101'),
  '4df568c2-4a68-52ab-80d6-380e5921d119'::uuid, 'PUL101: its catalogue course links to it');
select is((select display_title from public.institutional_courses where course_code = 'PUL101'),
  'Legal Methods I', 'PUL101: the catalogue shows the official title');
select is((select array_agg(distinct p.key order by p.key) from public.course_applicability a
  join public.academic_levels l on l.id = a.academic_level_id join public.academic_periods p on p.id = a.academic_period_id
  where a.institutional_course_id = (select id from public.institutional_courses where course_code = 'PUL101') and l.key = '100-level'),
  array['first-semester']::text[],
  'PUL101: it applies at the official level in every official semester');
-- Apply refuses a catalogue course missing from an official semester; the removed rows are then put back.
create temporary table bank_applicability_official_bank_pul101 on commit drop as
  select * from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'PUL101');
delete from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'PUL101')
  and academic_period_id = (select id from public.academic_periods where key = 'first-semester');
select throws_ok($$select private.official_bank_pul101('apply')$$, 'P0001',
  'Official bank PUL101: the catalogue course does not apply at the official level in every official semester',
  'PUL101: apply refuses a catalogue course missing from an official semester');
insert into public.course_applicability select * from bank_applicability_official_bank_pul101
  where (institutional_course_id, department_id, academic_level_id, academic_period_id) not in
    (select institutional_course_id, department_id, academic_level_id, academic_period_id from public.course_applicability);
-- PUL101 (legal-methods-1)
select is((select count(*)::int from public.managed_content_items where course_id = '4df568c2-4a68-52ab-80d6-380e5921d119'
  and kind = 'cbt_question' and published_revision is not null), 632,
  'PUL101: the final published count equals the bank count');
