create temporary table bank_before_official_bank_pul101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_pul101('apply'), 'unchanged', 'PUL101: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_pul101), 'PUL101: a rerun writes nothing');

select is(private.official_bank_pul101('rollback'), 'rolled-back', 'PUL101: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '4df568c2-4a68-52ab-80d6-380e5921d119' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'PUL101: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = '4df568c2-4a68-52ab-80d6-380e5921d119'
  and kind = 'cbt_question'), 632, 'PUL101: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = '4df568c2-4a68-52ab-80d6-380e5921d119' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 632,
  'PUL101: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_pul101('rollback'), 'unchanged', 'PUL101: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '1f6d959c-53e3-5e45-be28-fed0ca3fd521';
select throws_ok($$select private.official_bank_pul101('apply')$$, 'P0001',
  'Official bank PUL101: the published questions are not the audited set',
  'PUL101: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '1f6d959c-53e3-5e45-be28-fed0ca3fd521';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_pul101 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = 'cf7106a2-90ed-54d0-a768-e76ebf4386fe' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = 'cf7106a2-90ed-54d0-a768-e76ebf4386fe' and revision = 1;
select throws_ok($$select private.official_bank_pul101('apply')$$, 'P0001',
  'Official bank PUL101: cf7106a2-90ed-54d0-a768-e76ebf4386fe is not the same migration-owned question',
  'PUL101: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '4df568c2-4a68-52ab-80d6-380e5921d119' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'PUL101: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_pul101)
  where item_id = 'cf7106a2-90ed-54d0-a768-e76ebf4386fe' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_pul101),
  'PUL101: the failed apply wrote nothing');

