-- LAG-BUA111: a new course
select is((select content_key from public.courses where id = '0d6682a1-b7b0-5109-b86a-2fabbfbea8b4' and is_shared is null),
  'principles-marketing', 'LAG-BUA111: the new repository identity is registered, its sharing unresolved');
select is((select is_free from public.institutional_courses where course_code = 'LAG-BUA111'), false,
  'LAG-BUA111: the course is not free');
select is((select repository_course_id from public.institutional_courses where course_code = 'LAG-BUA111'),
  '0d6682a1-b7b0-5109-b86a-2fabbfbea8b4'::uuid, 'LAG-BUA111: its catalogue course links to it');
select is((select display_title from public.institutional_courses where course_code = 'LAG-BUA111'),
  'Principles of Marketing', 'LAG-BUA111: the catalogue shows the official title');
select is((select array_agg(distinct p.key order by p.key) from public.course_applicability a
  join public.academic_levels l on l.id = a.academic_level_id join public.academic_periods p on p.id = a.academic_period_id
  where a.institutional_course_id = (select id from public.institutional_courses where course_code = 'LAG-BUA111') and l.key = '100-level'),
  array['first-semester']::text[],
  'LAG-BUA111: it applies at the official level in every official semester');
-- Apply refuses a catalogue course missing from an official semester; the removed rows are then put back.
create temporary table bank_applicability_official_bank_lag_bua111 on commit drop as
  select * from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'LAG-BUA111');
delete from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'LAG-BUA111')
  and academic_period_id = (select id from public.academic_periods where key = 'first-semester');
select throws_ok($$select private.official_bank_lag_bua111('apply')$$, 'P0001',
  'Official bank LAG-BUA111: the catalogue course does not apply at the official level in every official semester',
  'LAG-BUA111: apply refuses a catalogue course missing from an official semester');
insert into public.course_applicability select * from bank_applicability_official_bank_lag_bua111
  where (institutional_course_id, department_id, academic_level_id, academic_period_id) not in
    (select institutional_course_id, department_id, academic_level_id, academic_period_id from public.course_applicability);
-- LAG-BUA111 (principles-marketing)
select is((select count(*)::int from public.managed_content_items where course_id = '0d6682a1-b7b0-5109-b86a-2fabbfbea8b4'
  and kind = 'cbt_question' and published_revision is not null), 688,
