select is((select count(*)::int from public.managed_content_items where course_id = '0d6682a1-b7b0-5109-b86a-2fabbfbea8b4'
  and kind = 'cbt_question'), 688,
  'LAG-BUA111: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_lag_bua111 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_lag_bua111('apply'), 'unchanged', 'LAG-BUA111: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_lag_bua111), 'LAG-BUA111: a rerun writes nothing');

select is(private.official_bank_lag_bua111('rollback'), 'rolled-back', 'LAG-BUA111: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '0d6682a1-b7b0-5109-b86a-2fabbfbea8b4' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'LAG-BUA111: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = '0d6682a1-b7b0-5109-b86a-2fabbfbea8b4'
  and kind = 'cbt_question'), 688, 'LAG-BUA111: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = '0d6682a1-b7b0-5109-b86a-2fabbfbea8b4' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 688,
  'LAG-BUA111: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_lag_bua111('rollback'), 'unchanged', 'LAG-BUA111: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = 'a78b37e2-8b59-5195-a26f-537735f42f8f';
select throws_ok($$select private.official_bank_lag_bua111('apply')$$, 'P0001',
  'Official bank LAG-BUA111: the published questions are not the audited set',
  'LAG-BUA111: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = 'a78b37e2-8b59-5195-a26f-537735f42f8f';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_lag_bua111 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = '12b9470a-16aa-5676-99a7-79282ab6a01f' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = '12b9470a-16aa-5676-99a7-79282ab6a01f' and revision = 1;
select throws_ok($$select private.official_bank_lag_bua111('apply')$$, 'P0001',
  'Official bank LAG-BUA111: 12b9470a-16aa-5676-99a7-79282ab6a01f is not the same migration-owned question',
  'LAG-BUA111: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '0d6682a1-b7b0-5109-b86a-2fabbfbea8b4' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'LAG-BUA111: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_lag_bua111)
  where item_id = '12b9470a-16aa-5676-99a7-79282ab6a01f' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_lag_bua111),
  'LAG-BUA111: the failed apply wrote nothing');

select is(private.official_bank_lag_bua111('apply'), 'applied', 'LAG-BUA111: apply after a rollback republishes the bank set');
