-- LAG-BUA123: a new course
select is((select content_key from public.courses where id = 'ced55987-74eb-5998-929a-c1d5275c5a3b' and is_shared is null),
  'marketing-communication', 'LAG-BUA123: the new repository identity is registered, its sharing unresolved');
select is((select is_free from public.institutional_courses where course_code = 'LAG-BUA123'), false,
  'LAG-BUA123: the course is not free');
select is((select repository_course_id from public.institutional_courses where course_code = 'LAG-BUA123'),
  'ced55987-74eb-5998-929a-c1d5275c5a3b'::uuid, 'LAG-BUA123: its catalogue course links to it');
select is((select display_title from public.institutional_courses where course_code = 'LAG-BUA123'),
  'Marketing Communication', 'LAG-BUA123: the catalogue shows the official title');
select is((select array_agg(distinct p.key order by p.key) from public.course_applicability a
  join public.academic_levels l on l.id = a.academic_level_id join public.academic_periods p on p.id = a.academic_period_id
  where a.institutional_course_id = (select id from public.institutional_courses where course_code = 'LAG-BUA123') and l.key = '100-level'),
  array['first-semester']::text[],
  'LAG-BUA123: it applies at the official level in every official semester');
-- Apply refuses a catalogue course missing from an official semester; the removed rows are then put back.
create temporary table bank_applicability_official_bank_lag_bua123 on commit drop as
  select * from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'LAG-BUA123');
delete from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'LAG-BUA123')
  and academic_period_id = (select id from public.academic_periods where key = 'first-semester');
select throws_ok($$select private.official_bank_lag_bua123('apply')$$, 'P0001',
  'Official bank LAG-BUA123: the catalogue course does not apply at the official level in every official semester',
  'LAG-BUA123: apply refuses a catalogue course missing from an official semester');
insert into public.course_applicability select * from bank_applicability_official_bank_lag_bua123
  where (institutional_course_id, department_id, academic_level_id, academic_period_id) not in
    (select institutional_course_id, department_id, academic_level_id, academic_period_id from public.course_applicability);
-- LAG-BUA123 (marketing-communication)
