  on i.id = p.item_id where i.course_id = 'ced55987-74eb-5998-929a-c1d5275c5a3b' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 516,
  'LAG-BUA123: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_lag_bua123('rollback'), 'unchanged', 'LAG-BUA123: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '50923867-f356-527e-bbaf-fb5069c9e271';
select throws_ok($$select private.official_bank_lag_bua123('apply')$$, 'P0001',
  'Official bank LAG-BUA123: the published questions are not the audited set',
  'LAG-BUA123: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '50923867-f356-527e-bbaf-fb5069c9e271';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_lag_bua123 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = '5170df65-f1e5-5314-ba7e-2e497e4e8306' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = '5170df65-f1e5-5314-ba7e-2e497e4e8306' and revision = 1;
select throws_ok($$select private.official_bank_lag_bua123('apply')$$, 'P0001',
  'Official bank LAG-BUA123: 5170df65-f1e5-5314-ba7e-2e497e4e8306 is not the same migration-owned question',
  'LAG-BUA123: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'ced55987-74eb-5998-929a-c1d5275c5a3b' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'LAG-BUA123: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_lag_bua123)
  where item_id = '5170df65-f1e5-5314-ba7e-2e497e4e8306' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_lag_bua123),
  'LAG-BUA123: the failed apply wrote nothing');

