select is((select count(*)::int from public.managed_content_items where course_id = 'caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1'
  and kind = 'cbt_question'), 572,
  'LAG-BUA125: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_lag_bua125 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_lag_bua125('apply'), 'unchanged', 'LAG-BUA125: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_lag_bua125), 'LAG-BUA125: a rerun writes nothing');

select is(private.official_bank_lag_bua125('rollback'), 'rolled-back', 'LAG-BUA125: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'LAG-BUA125: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = 'caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1'
  and kind = 'cbt_question'), 572, 'LAG-BUA125: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = 'caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 572,
  'LAG-BUA125: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_lag_bua125('rollback'), 'unchanged', 'LAG-BUA125: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '6cdf10e3-0ba6-5d73-b68f-20366ed96ce0';
select throws_ok($$select private.official_bank_lag_bua125('apply')$$, 'P0001',
  'Official bank LAG-BUA125: the published questions are not the audited set',
  'LAG-BUA125: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '6cdf10e3-0ba6-5d73-b68f-20366ed96ce0';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_lag_bua125 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = '4d48cab0-e2d3-51ea-b6ce-b92dd4514a04' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = '4d48cab0-e2d3-51ea-b6ce-b92dd4514a04' and revision = 1;
select throws_ok($$select private.official_bank_lag_bua125('apply')$$, 'P0001',
  'Official bank LAG-BUA125: 4d48cab0-e2d3-51ea-b6ce-b92dd4514a04 is not the same migration-owned question',
  'LAG-BUA125: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'caf0ea5d-6cc0-5bd0-8719-c6f1a95ceec1' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'LAG-BUA125: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_lag_bua125)
  where item_id = '4d48cab0-e2d3-51ea-b6ce-b92dd4514a04' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_lag_bua125),
  'LAG-BUA125: the failed apply wrote nothing');

select is(private.official_bank_lag_bua125('apply'), 'applied', 'LAG-BUA125: apply after a rollback republishes the bank set');
