select is((select count(*)::int from public.managed_content_items where course_id = '8e4bf369-a375-52bc-b5c2-fa55b4d5676c'
  and kind = 'cbt_question'), 820,
  'FIN216: retired questions are kept, unpublished');

create temporary table bank_before_official_bank_fin216 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_fin216('apply'), 'unchanged', 'FIN216: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_fin216), 'FIN216: a rerun writes nothing');

select is(private.official_bank_fin216('rollback'), 'rolled-back', 'FIN216: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '8e4bf369-a375-52bc-b5c2-fa55b4d5676c' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'FIN216: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = '8e4bf369-a375-52bc-b5c2-fa55b4d5676c'
  and kind = 'cbt_question'), 820, 'FIN216: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = '8e4bf369-a375-52bc-b5c2-fa55b4d5676c' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 820,
  'FIN216: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_fin216('rollback'), 'unchanged', 'FIN216: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '264fbe06-a84d-5213-9c6c-23dd93f0fc21';
select throws_ok($$select private.official_bank_fin216('apply')$$, 'P0001',
  'Official bank FIN216: the published questions are not the audited set',
  'FIN216: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '264fbe06-a84d-5213-9c6c-23dd93f0fc21';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_fin216 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = 'fb133155-6257-51d5-97bc-af5e16a9634f' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = 'fb133155-6257-51d5-97bc-af5e16a9634f' and revision = 1;
select throws_ok($$select private.official_bank_fin216('apply')$$, 'P0001',
  'Official bank FIN216: fb133155-6257-51d5-97bc-af5e16a9634f is not the same migration-owned question',
  'FIN216: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = '8e4bf369-a375-52bc-b5c2-fa55b4d5676c' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'FIN216: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_fin216)
  where item_id = 'fb133155-6257-51d5-97bc-af5e16a9634f' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_fin216),
  'FIN216: the failed apply wrote nothing');

