-- TAX-CM223: a new course
select is((select content_key from public.courses where id = 'b7bba625-d122-5afa-8b13-127d96411059' and is_shared is null),
  'business-taxation-2', 'TAX-CM223: the new repository identity is registered, its sharing unresolved');
select is((select is_free from public.institutional_courses where course_code = 'TAX-CM223'), false,
  'TAX-CM223: the course is not free');
select is((select repository_course_id from public.institutional_courses where course_code = 'TAX-CM223'),
  'b7bba625-d122-5afa-8b13-127d96411059'::uuid, 'TAX-CM223: its catalogue course links to it');
select is((select display_title from public.institutional_courses where course_code = 'TAX-CM223'),
  'Business Taxation II', 'TAX-CM223: the catalogue shows the official title');
select is((select array_agg(distinct p.key order by p.key) from public.course_applicability a
  join public.academic_levels l on l.id = a.academic_level_id join public.academic_periods p on p.id = a.academic_period_id
  where a.institutional_course_id = (select id from public.institutional_courses where course_code = 'TAX-CM223') and l.key = '200-level'),
  array['second-semester']::text[],
  'TAX-CM223: it applies at the official level in every official semester');
-- Apply refuses a catalogue course missing from an official semester; the removed rows are then put back.
create temporary table bank_applicability_official_bank_tax_cm223 on commit drop as
  select * from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'TAX-CM223');
delete from public.course_applicability where institutional_course_id = (select id from public.institutional_courses where course_code = 'TAX-CM223')
  and academic_period_id = (select id from public.academic_periods where key = 'second-semester');
select throws_ok($$select private.official_bank_tax_cm223('apply')$$, 'P0001',
  'Official bank TAX-CM223: the catalogue course does not apply at the official level in every official semester',
  'TAX-CM223: apply refuses a catalogue course missing from an official semester');
insert into public.course_applicability select * from bank_applicability_official_bank_tax_cm223
  where (institutional_course_id, department_id, academic_level_id, academic_period_id) not in
    (select institutional_course_id, department_id, academic_level_id, academic_period_id from public.course_applicability);
-- TAX-CM223 (business-taxation-2)
select is((select count(*)::int from public.managed_content_items where course_id = 'b7bba625-d122-5afa-8b13-127d96411059'
  and kind = 'cbt_question' and published_revision is not null), 396,
