create temporary table bank_before_official_bank_tax_cm223 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts;
select is(private.official_bank_tax_cm223('apply'), 'unchanged', 'TAX-CM223: a rerun reports nothing to do');
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_before_official_bank_tax_cm223), 'TAX-CM223: a rerun writes nothing');

select is(private.official_bank_tax_cm223('rollback'), 'rolled-back', 'TAX-CM223: rollback runs');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'b7bba625-d122-5afa-8b13-127d96411059' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'TAX-CM223: rollback republishes exactly the audited set at revision one');
select is((select count(*)::int from public.managed_content_items where course_id = 'b7bba625-d122-5afa-8b13-127d96411059'
  and kind = 'cbt_question'), 396, 'TAX-CM223: rollback deletes nothing');
select is((select count(*)::int from public.managed_content_publications p join public.managed_content_items i
  on i.id = p.item_id where i.course_id = 'b7bba625-d122-5afa-8b13-127d96411059' and p.acted_by = '00000000-0000-4000-8000-000000000043'
  and p.action = 'unpublish'), 396,
  'TAX-CM223: every retirement and every rollback unpublish is in the publish history');
select is(private.official_bank_tax_cm223('rollback'), 'unchanged', 'TAX-CM223: a second rollback does nothing');

-- A live set that is neither the audited nor the bank set is refused, and nothing changes.
update public.managed_content_items set published_revision = 1 where id = '6706bf70-3c73-5e0a-a58b-f56c57dd627b';
select throws_ok($$select private.official_bank_tax_cm223('apply')$$, 'P0001',
  'Official bank TAX-CM223: the published questions are not the audited set',
  'TAX-CM223: apply refuses a published set other than the audited one');
update public.managed_content_items set published_revision = null where id = '6706bf70-3c73-5e0a-a58b-f56c57dd627b';

-- A failure on the last question rolls back everything written before it. After the rollback that question
-- exists unpublished; its stored text is changed so it is no longer the bank's, then restored.
create temporary table bank_conflict_official_bank_tax_cm223 on commit drop as select (select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items) counts,
  (select payload from public.managed_content_revisions where item_id = '8b6ea131-38b9-5d58-aba9-fdba1f17cb51' and revision = 1) payload;
update public.managed_content_revisions set payload = jsonb_set(payload, '{prompt}', '"Not the bank text"')
  where item_id = '8b6ea131-38b9-5d58-aba9-fdba1f17cb51' and revision = 1;
select throws_ok($$select private.official_bank_tax_cm223('apply')$$, 'P0001',
  'Official bank TAX-CM223: 8b6ea131-38b9-5d58-aba9-fdba1f17cb51 is not the same migration-owned question',
  'TAX-CM223: apply fails on a conflicting last question');
select ok((select coalesce(jsonb_object_agg(id::text, published_revision), '{}') from public.managed_content_items
  where course_id = 'b7bba625-d122-5afa-8b13-127d96411059' and kind = 'cbt_question' and published_revision is not null) = $audited_set${}$audited_set$::jsonb,
  'TAX-CM223: a failed apply leaves the audited set published');
update public.managed_content_revisions set payload = (select payload from bank_conflict_official_bank_tax_cm223)
  where item_id = '8b6ea131-38b9-5d58-aba9-fdba1f17cb51' and revision = 1;
select is((select row(count(*), (select count(*) from public.managed_content_revisions), (select count(*) from public.managed_content_reviews), (select count(*) from public.managed_content_publications))::text from public.managed_content_items), (select counts from bank_conflict_official_bank_tax_cm223),
  'TAX-CM223: the failed apply wrote nothing');

